class Solution:
    def sumOfBeauties(self, nums):
        n = len(nums)
        ans = 0
        for i in range(1, n - 1):
            ok2 = all(v < nums[i] for v in nums[:i]) and all(nums[i] < v for v in nums[i + 1:])
            if ok2:
                ans += 2
            elif nums[i - 1] < nums[i] < nums[i + 1]:
                ans += 1
        return ans

