            bool ok2 = true;
            for (int j = 0; j < i && ok2; j++) ok2 = nums[j] < nums[i];
            for (int j = i + 1; j < n && ok2; j++) ok2 = nums[i] < nums[j];
            if (ok2) ans += 2;
            else if (nums[i - 1] < nums[i] && nums[i] < nums[i + 1]) ans++;
        }
        return ans;
    }
};

