        int n = nums.size();
        vector<int> sufMin(n + 1, INT_MAX);
        for (int i = n - 1; i >= 0; i--) sufMin[i] = min(sufMin[i + 1], nums[i]);
        int ans = 0, runMax = nums[0];
        for (int i = 1; i < n - 1; i++) {
            if (runMax < nums[i] && nums[i] < sufMin[i + 1]) ans += 2;
            else if (nums[i - 1] < nums[i] && nums[i] < nums[i + 1]) ans++;
            runMax = max(runMax, nums[i]);
        }
        return ans;
    }
};

